from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class NiddVersionCMV1(SchemaObject):
    adaptation_id = SchemaField(name="adaptation_id", not_null=True)
    version = SchemaField(name="version", not_null=True)

    def __init__(self, adaptation_id=None, version=None):
        self.adaptation_id = adaptation_id
        self.version = version

        super(NiddVersionCMV1, self).__init__()


class ReleaseVersionCMV1(SchemaObject):
    release_version = SchemaField(name="release_version", not_null=False)
    adaptation_versions = SchemaField(name="adaptation_versions", klass=NiddVersionCMV1, many=True, not_null=True)

    def __init__(self, release_version=None, adaptation_versions=None):
        self.release_version = release_version
        self.adaptation_versions = adaptation_versions

        super(ReleaseVersionCMV1, self).__init__()


class LoadPlanTemplateInfoCMV1(SchemaObject):
    content_type = SchemaField(name="content_type", not_null=True)
    version = SchemaField(name="version", klass=ReleaseVersionCMV1, not_null=True)
    migration_needed = SchemaField(name="migration_needed", not_null=True)
    supported_versions = SchemaField(name="supported_versions", klass=ReleaseVersionCMV1, many=True, not_null=False)

    def __init__(self, content_type=None, version=None, migration_needed=None, supported_versions=None):
        self.content_type = content_type
        self.version = version
        self.migration_needed = migration_needed
        self.supported_versions = supported_versions

        super(LoadPlanTemplateInfoCMV1, self).__init__()
